Here’s a clean, **main + function** version of **reversing a Singly Linked List (SLL)** in **C** — written in a way you can directly run and understand line by line:

---

### ✅ **C Program: Reverse a Singly Linked List**

```c
#include <stdio.h>
#include <stdlib.h>

// Structure definition for a singly linked list node
struct Node {
    int data;
    struct Node* next;
};

// Function to create a new node
struct Node* createNode(int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a node at the end
struct Node* insertEnd(struct Node* head, int data) {
    struct Node* newNode = createNode(data);
    if (head == NULL)
        return newNode;

    struct Node* temp = head;
    while (temp->next != NULL)
        temp = temp->next;

    temp->next = newNode;
    return head;
}

// Function to print the linked list
void display(struct Node* head) {
    struct Node* temp = head;
    while (temp != NULL) {
        printf("%d -> ", temp->data);
        temp = temp->next;
    }
    printf("NULL\n");
}

// Function to reverse the linked list
struct Node* reverseList(struct Node* head) {
    struct Node* prev = NULL;
    struct Node* current = head;
    struct Node* next = NULL;

    while (current != NULL) {
        next = current->next;     // store next node
        current->next = prev;     // reverse the link
        prev = current;           // move prev forward
        current = next;           // move current forward
    }
    return prev; // new head
}

// Main function
int main() {
    struct Node* head = NULL;

    // Create linked list: 10 -> 20 -> 30 -> 40 -> NULL
    head = insertEnd(head, 10);
    head = insertEnd(head, 20);
    head = insertEnd(head, 30);
    head = insertEnd(head, 40);

    printf("Original List:\n");
    display(head);

    // Reverse the list
    head = reverseList(head);

    printf("Reversed List:\n");
    display(head);

    return 0;
}
```

---

### ⚙️ **Explanation**

- **`reverseList()` logic:**
  - Uses three pointers:  
    - `prev` → previous node  
    - `current` → current node  
    - `next` → store next node temporarily  
  - Reverses the `next` pointer one by one.

- **Output:**
  ```
  Original List:
  10 -> 20 -> 30 -> 40 -> NULL
  Reversed List:
  40 -> 30 -> 20 -> 10 -> NULL
  ```

